import json, re
raw = open('/tmp/ci_logs.json').read()
text = json.loads(raw)
parts = re.split(r'--- (\d+_[^\n]+\.txt) ---', text)
jobs = {}
for i in range(1, len(parts), 2):
    jobs[parts[i]] = parts[i+1]
crap = jobs['16_CRAP + duplication.txt']
lines = crap.split('\n')
def clean(l):
    return re.sub(r'^\d{4}-\d\d-\d\dT[\d:.]+Z ', '', l)
for i in range(355, 382):
    print(i, clean(lines[i])[:250])
print('===== around failure =====')
for i in range(8120, 8160):
    print(i, clean(lines[i])[:250])
EOF

