  final body = <String>[];
  var j = i + 1;
  var closed = false;
  while (j < lines.length) {
    if (_fenceLine.hasMatch(lines[j])) {
      closed = true;
      break;
    }
    body.add(lines[j]);
    j++;
  }
  return (
    span: _LedgerSpan(
      startLine: i,
      endLine: closed ? j : lines.length - 1,
      body: body.join('\n'),
    ),
    nextLine: closed ? j + 1 : lines.length,
  );
}

