  final spans = <_LedgerSpan>[];
  var i = 0;
  while (i < lines.length) {
    final fenced = _fencedLedgerSpanAt(lines, i);
    if (fenced != null) {
      spans.add(fenced.span);
      i = fenced.nextLine;
      continue;
