    final replaced = List<ContentBlock>.of(content);
    replaced[i] = block.copyWith(text: resolution.strippedText);
    final stripped = message.copyWith(content: replaced);
    stash.add(
      _StrippedLedger(
        ledger: resolution.ledger,
        original: message,
        stripped: stripped,
      ),
    );
    return stripped;
  }
  return null;
