/// The FinalizeGate `MessageEndEvent` interceptor (gh-1516 review): hosts
/// persist (`_persistIncremental`) and render (`_onAssistantMessageEnd`)
/// the message a `MessageEndEvent` carries — anything the end-of-run fold
/// rewrites later never reaches the session JSONL or the flush. In gate
/// mode each assistant message is therefore stripped at this choke point,
/// BEFORE the event is forwarded, and the strip is stashed for the
/// end-of-run fold. Non-assistant events and gate-off turns pass through.
AgentEventSink _finalizeGateStrippingSink(
  AgentEventSink emit,
  List<_StrippedLedger> stash,
  bool Function() gateOn,
) {
  return (AgentEvent event) {
    if (!gateOn() || event is! MessageEndEvent) return emit(event);
    final stripped = _stripAssistantLedger(event.message);
    if (stripped == null) return emit(event);
    return emit(MessageEndEvent(stripped.stripped));
  };
}
